package server

import (
	"net/http"

	httpSwagger "github.com/swaggo/http-swagger/v2"
)

// MountAPIDocs serves the generated API documentation:
//
//	GET /openapi.json       OpenAPI 3 (converted from the swag output)
//	GET /swagger/doc.json   Swagger 2.0 as generated by swag
//	GET /swagger/           Swagger UI, pointed at /openapi.json
//
// The bytes come from internal/apidocs (embedded at build time).
func MountAPIDocs(s *Server, openapiJSON, swaggerJSON []byte) {
	serve := func(b []byte) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/json; charset=utf-8")
			w.Header().Set("Cache-Control", "no-cache")
			_, _ = w.Write(b)
		}
	}
	s.mux.Handle("GET /openapi.json", serve(openapiJSON))
	s.mux.Handle("GET /swagger/doc.json", serve(swaggerJSON))
	s.mux.Handle("GET /swagger/", httpSwagger.Handler(httpSwagger.URL("/openapi.json")))
	s.mux.Handle("GET /swagger", http.RedirectHandler("/swagger/index.html", http.StatusMovedPermanently))
}
